from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(input_str):
        groups = []
        current_group = ""
        open_count = 0

        for char in input_str:
            if char == '(':
                open_count += 1
            elif char == ')':
                open_count -= 1

            current_group += char

            if open_count == 0:
                groups.append(current_group)
                current_group = ""

        return groups

    def remove_spaces(groups):
        return [group.replace(" ", "") for group in groups]

    def split_groups(groups):
        return [group for group in groups if group != '']

    extracted_groups = extract_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)
    final_groups = split_groups(cleaned_groups)

    return final_groups

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

